/**
 * Row height constants used for sticky-pinning offset calculations.
 * These must match the rendered row heights produced by the CSS padding tokens.
 * If the design system row height changes, update both here and in the
 * corresponding SCSS (TableCell.module.scss compact/normal padding).
 */
var ROW_HEIGHT_PX = 56;
var ROW_HEIGHT_COMPACT_PX = 40;

export { ROW_HEIGHT_COMPACT_PX, ROW_HEIGHT_PX };
